 plan={'schema':c.PLAN_SCHEMA,'status':'HELD_SOURCE_REVIEW_AND_ROOT_CONTROL_ADMISSION','role':c.ROLE,'bound_recipe':row(contract),'source_manifest':row(manifest_path),'baseline':baseline,'posthoc_admission':row('evidence/checkm2_posthoc_v002/admission.json'),'baseline_annotation':row(oldrun+'/annotation/annotation_receipt.json'),'baseline_quality_binding':row(oldrun+'/protein_quality_binding.json'),'baseline_diamond_directory':oldrun+'/quality_output/diamond_output','input':bound['reference_input_from_metadata_only'],'feature_schema':bound['basis']['corrected_feature_schema'],'original_prodigal_source_sha256':'4d962b423281b81edf3e9eec7ce3219388a0df8ae52c13cde883419826592b6f','transform':{'width':61,'line_ending':'LF','headers_record_order_sequence_case_exact':True,'no_op_substitution_or_retry':False},'limits':c.LIMITS,'stock_resume_force_retry':False,'derived_input_path':None,'derived_input_sha256':None,'variant_preparation_requires_root_protocol':True,'standard_progress_path':'state/stages/04.json','dedicated_progress_path':'state/checkm2_protein_format_invariance_v002_progress.json','post_success_stage04_status':'PENDING_BENCHMARK','production_panel_acceptance':False}
