 admission={'schema':'TREE2_PROTEIN_FORMAT_CONTROL_ADMISSION_V002','status':'DRAFT_NOT_ADMITTED','role':c.ROLE,'max_attempts':1,'format_control_execution_authorized':False,'input_plan_path':plan_path.relative_to(R).as_posix(),'input_plan_sha256':c.v.sha(plan_path),'source_manifest_sha256':c.v.sha(manifest_path),'root_baseline_acceptance_sha256':c.ROOT_ACCEPTANCE_SHA,'limits':c.LIMITS,'monitor_standard_stage04_ready':False,'source_math_GO':False,'resource_lifecycle_GO':False,'external_actual_native_exit_and_lease_proof_before_comparison':True,'production_panel_acceptance':False,'control_admission_destination':c.ADMISSION.relative_to(R).as_posix()}
